[TestClass][DoNotParallelize]public sealed class R54HomeUiTests
{
 static string Image(string root,string name,byte blue){var a=new byte[96*64*3];for(int y=0;y<64;y++)for(int x=0;x<96;x++){int i=(y*96+x)*3;a[i]=(byte)(x*2);a[i+1]=(byte)(y*3);a[i+2]=blue;}var b=BitmapSource.Create(96,64,96,96,PixelFormats.Rgb24,null,a,96*3);var p=Path.Combine(root,name+".png");var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(b));using var f=File.Create(p);png.Save(f);return p;}
 static void Layout(FrameworkElement v,int width){v.Measure(new Size(width,width==1366?768:1080));v.Arrange(new Rect(0,0,width,width==1366?768:1080));v.UpdateLayout();}
 static void Invoke(PhotoGradePageView v,string method){var m=typeof(PhotoGradePageView).GetMethod(method,System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance)!;m.Invoke(v,m.GetParameters().Length==0?null:[v,new RoutedEventArgs()]);}
 static async Task Settle(ReferenceColorWorkspaceViewModel vm){for(int i=0;i<500&&!vm.Editor.IsSettled;i++)await Task.Delay(15);Assert.IsTrue(vm.Editor.IsSettled,vm.Editor.StatusText);await vm.LayerThumbnailWork;}
 static string Hash(BitmapSource b){var r=new FormatConvertedBitmap(b,PixelFormats.Bgra32,null,0);var a=new byte[r.PixelWidth*r.PixelHeight*4];r.CopyPixels(a,r.PixelWidth*4,0);return Convert.ToHexString(SHA256.HashData(a));}
 [TestMethod]public Task FourProductionStatesSelectedNodeThumbnailsRestoreAndFrameGallery()=>RunSta(async()=>
 {
  var root=Environment.GetEnvironmentVariable("KITAO_R54_HOME_UI");if(root is null){Assert.Inconclusive("Explicit household offscreen output required");return;}Directory.CreateDirectory(root);EnsureTestApplication();using var vm=new ReferenceColorWorkspaceViewModel(new Dialogs());await vm.LoadTargetAsync(Image(root,"first",35));await vm.CreateR53VariantAsync(true);vm.Editor.AddAdjustmentNodeCommand.Execute("BasicTone");vm.Editor.SetToolParameter(ColorStudioToolCatalog.GetParameters(ColorStudioNodeType.BasicTone).Single(p=>p.Key=="exposure"),.7);vm.Editor.AddMaskStroke(new([new(.4,.5)],.3,.5,.7,1));vm.Editor.AddAdjustmentNodeCommand.Execute("Curve");Assert.IsTrue(vm.Editor.AddParallelGraphBranch());await Settle(vm);
  var view=new PhotoGradePageView{DataContext=vm};Layout(view,1366);vm.R53Professional=true;Invoke(view,"OpenR53Panel");view.ApplyR53Layout();view.UpdateLayout();Assert.AreEqual(Visibility.Collapsed,((Grid)view.FindName("R53NodeContent")).Visibility);
  // User expansion persists and isn't overwritten by resizing or reattaching.
  Invoke(view,"R53ToggleNodes");Assert.AreEqual(false,vm.Layout.R54GraphCollapsed);Layout(view,1920);view.DataContext=null;view.DataContext=vm;Layout(view,1366);view.ApplyR53Layout();Assert.AreEqual(false,vm.Layout.R54GraphCollapsed);
  var curve=vm.Editor.AdjustmentNodes.First(n=>n.Type==ColorStudioNodeType.Curve);vm.Editor.SelectedAdjustmentNode=curve;view.ApplyR53Layout();var scroll=(ScrollViewer)view.FindName("AdjustmentScroll");var sections=((StackPanel)scroll.Content).Children.OfType<Expander>().Where(e=>e.Visibility==Visibility.Visible).ToArray();Assert.HasCount(1,sections);Assert.AreEqual("AdjustmentScroll.4",sections[0].Tag);Assert.IsNotNull(vm.LayerThumbnailContext);foreach(var id in vm.Editor.AdjustmentStack.Graph!.RoutedIds(vm.Editor.AdjustmentNodes.ToArray()))Assert.IsTrue(vm.LayerThumbnailContext!.Outputs.ContainsKey(id));
  var before=JsonSerializer.Serialize(vm.Editor.AdjustmentStack);vm.R53Professional=false;view.ApplyR53Layout();vm.Editor.ProfessionalGroupAmount=.4;var amount=vm.Editor.AdjustmentStack.Graph.GroupAmount;vm.R53Professional=true;Assert.AreEqual(.4,amount);Assert.AreEqual(before,JsonSerializer.Serialize(vm.Editor.AdjustmentStack with{Graph=vm.Editor.AdjustmentStack.Graph with{GroupAmount=1}}));
  var graphVersion=vm.ActiveTarget!.ActiveEditVersionId;
  void Capture(string state,int width){Layout(view,width);view.ApplyR53Layout();view.UpdateLayout();if(vm.R53Professional){var graph=((Grid)view.FindName("R53NodeContent")).Children.OfType<StudioNodeGraphView>().Single();graph.Fit();view.UpdateLayout();}var bitmap=new RenderTargetBitmap(width,width==1366?768:1080,96,96,PixelFormats.Pbgra32);bitmap.Render(view);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using var f=File.Create(Path.Combine(root,state+"-"+width+"-OFFSCREEN.png"));png.Save(f);}
  foreach(var width in new[]{1366,1920}){await vm.SwitchEditVersionAsync(graphVersion!.Value);await Settle(vm);vm.R53Professional=false;((TabControl)view.FindName("EditModes")).SelectedIndex=0;Invoke(view,"OpenR53Panel");Capture("simple",width);vm.R53Professional=true;Capture("professional",width);vm.R53Professional=false;Invoke(view,"R53InstantTab");vm.InstantCameraAnimation=false;vm.SelectedLightPrintFrameId="orig.01";await vm.LightPrintPreviewWork;vm.RequestFramePreviews();await vm.FramePreviewWork;Assert.AreEqual(vm.LightPrintFrameChoices.Count,vm.FramePreviews.Count,vm.LightPrintStatus);Assert.IsTrue(vm.FramePreviews.Values.All(b=>Math.Max(b.PixelWidth,b.PixelHeight)<=128));Capture("film-draft",width);await vm.DevelopLightPrintCommand.ExecuteAsync(null);Assert.IsTrue(vm.IsLightPrintLocked,vm.LightPrintStatus);Capture("developed",width);vm.ReshootLightPrintCommand.Execute(null);vm.CancelLightPrintPreviewCommand.Execute(null);await vm.LightPrintPreviewWork;}
  await vm.SwitchEditVersionAsync(graphVersion!.Value);var connected=vm.Editor.GraphView;Assert.IsTrue(vm.Editor.CommitGraph(connected with{Edges=connected.Edges.Where(e=>e.To!=StudioNodeGraph.Output).ToArray()}));StringAssert.Contains(vm.Editor.GraphRouteStatus,"原图");Assert.IsTrue(vm.Editor.CommitGraph(connected));await Settle(vm);vm.RequestFramePreviews();await vm.FramePreviewWork;var prior=Hash(vm.FramePreviews["orig.01"]);await vm.LoadTargetAsync(Image(root,"second",220));Assert.AreEqual(0,vm.FramePreviews.Count);vm.RequestFramePreviews();await vm.FramePreviewWork;Assert.AreNotEqual(prior,Hash(vm.FramePreviews["orig.01"]));view.DataContext=null;vm.ExitInstantPresentationForLifecycle();await vm.FramePreviewWork;Assert.AreEqual(0,vm.FramePreviews.Count);await File.WriteAllTextAsync(Path.Combine(root,"RESULT.json"),JsonSerializer.Serialize(new{fourStates=true,nodeOutputs=true,masks=true,frameCurrentPhoto=true,ABNotStale=true,physicalPointer=false,physicalDpi=false,design54Archive="MISSING_LOCAL"}));
 });
